CREATE TABLE "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE "auth_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "first_name" varchar(150) NOT NULL);
CREATE TABLE "auth_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "charts_artist" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "canonical_name" varchar(200) NOT NULL);
CREATE TABLE "charts_artistalias" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "alias_text" varchar(200) NOT NULL UNIQUE, "artist_id" bigint NOT NULL REFERENCES "charts_artist" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "charts_chart" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "category" varchar(10) NOT NULL, "method" varchar(10) NOT NULL, "publication_weekday" smallint unsigned NOT NULL CHECK ("publication_weekday" >= 0), CONSTRAINT "unique_chart_category_method" UNIQUE ("category", "method"));
CREATE TABLE "charts_chartentry" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "week_date" date NOT NULL, "position" smallint unsigned NOT NULL CHECK ("position" >= 0), "printed_last_week_position" smallint unsigned NULL CHECK ("printed_last_week_position" >= 0), "printed_peak_position" smallint unsigned NULL CHECK ("printed_peak_position" >= 0), "printed_weeks_on_chart" smallint unsigned NULL CHECK ("printed_weeks_on_chart" >= 0), "printed_anomaly_note" varchar(300) NOT NULL, "chart_id" bigint NOT NULL REFERENCES "charts_chart" ("id") DEFERRABLE INITIALLY DEFERRED, "recording_id" bigint NOT NULL REFERENCES "charts_recording" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "unique_chart_week_position_recording" UNIQUE ("chart_id", "week_date", "position", "recording_id"));
CREATE TABLE "charts_chartera" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "printed_name" varchar(200) NOT NULL, "start_date" date NOT NULL, "end_date" date NULL, "max_position" smallint unsigned NOT NULL CHECK ("max_position" >= 0), "chart_id" bigint NOT NULL REFERENCES "charts_chart" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "charts_discogscandidate" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "discogs_release_id" integer unsigned NULL CHECK ("discogs_release_id" >= 0), "discogs_master_id" integer unsigned NULL CHECK ("discogs_master_id" >= 0), "title" varchar(300) NOT NULL, "artist" varchar(300) NOT NULL, "label" varchar(200) NOT NULL, "catalog_number" varchar(100) NOT NULL, "year" smallint unsigned NULL CHECK ("year" >= 0), "country" varchar(100) NOT NULL, "format" varchar(200) NOT NULL, "thumb_url" varchar(500) NOT NULL, "confidence" varchar(6) NOT NULL, "rank" smallint unsigned NOT NULL CHECK ("rank" >= 0), "raw_data" text NULL CHECK ((JSON_VALID("raw_data") OR "raw_data" IS NULL)), "match_id" bigint NOT NULL REFERENCES "charts_discogsmatch" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "charts_discogsmatch" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "status" varchar(12) NOT NULL, "confidence" varchar(6) NOT NULL, "discogs_release_id" integer unsigned NULL CHECK ("discogs_release_id" >= 0), "discogs_master_id" integer unsigned NULL CHECK ("discogs_master_id" >= 0), "matched_title" varchar(300) NOT NULL, "matched_artist" varchar(300) NOT NULL, "matched_label" varchar(200) NOT NULL, "matched_catalog_number" varchar(100) NOT NULL, "matched_year" smallint unsigned NULL CHECK ("matched_year" >= 0), "matched_country" varchar(100) NOT NULL, "matched_format" varchar(200) NOT NULL, "genres" text NOT NULL CHECK ((JSON_VALID("genres") OR "genres" IS NULL)), "styles" text NOT NULL CHECK ((JSON_VALID("styles") OR "styles" IS NULL)), "songwriters" varchar(500) NOT NULL, "producers" varchar(500) NOT NULL, "raw_data" text NULL CHECK ((JSON_VALID("raw_data") OR "raw_data" IS NULL)), "note" varchar(500) NOT NULL, "searched_at" datetime NULL, "updated_at" datetime NOT NULL, "recording_id" bigint NOT NULL UNIQUE REFERENCES "charts_recording" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "charts_label" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL UNIQUE);
CREATE TABLE "charts_recording" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "catalog_number" varchar(30) NOT NULL, "credit_text" varchar(300) NOT NULL, "label_id" bigint NOT NULL REFERENCES "charts_label" ("id") DEFERRABLE INITIALLY DEFERRED, "song_id" bigint NOT NULL REFERENCES "charts_song" ("id") DEFERRABLE INITIALLY DEFERRED, "side" varchar(4) NOT NULL, "reissue_of_id" bigint NULL REFERENCES "charts_recording" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "unique_label_catalog_side" UNIQUE ("label_id", "catalog_number", "side"));
CREATE TABLE "charts_recordingcredit" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "credit_order" smallint unsigned NOT NULL CHECK ("credit_order" >= 0), "artist_id" bigint NOT NULL REFERENCES "charts_artist" ("id") DEFERRABLE INITIALLY DEFERRED, "recording_id" bigint NOT NULL REFERENCES "charts_recording" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "unique_recording_artist" UNIQUE ("recording_id", "artist_id"), CONSTRAINT "unique_recording_credit_order" UNIQUE ("recording_id", "credit_order"));
CREATE TABLE "charts_song" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(300) NOT NULL);
CREATE TABLE "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE sqlite_sequence(name,seq);
